// always scale to viewport\n const vw=innerWidth/1280; return vw }\nwindow.__zoom=/zoom=1/.test(location.search);\nfunction camera(app,t,zk){const base=innerWidth/1280;let s=1,fx=640,fy=400;\n if(window.__zoom&&zk){for(const k of zk){const a=eio(seg(t,k[0]-.5,k[0]))*(1-eio(seg(t,k[1],k[1]+.5)));if(a>0){s=lerp(1,k[2],a);fx=lerp(640,k[3],a);fy=lerp(400,k[4],a)}}}\n const sc=base*s;const tx=640*base-fx*sc,ty=400*base-fy*sc; // focus point -> centre\n const f=Math.min(0,Math.max(tx,innerWidth-1280*sc)),g=Math.min(0,Math.max(ty,innerHeight-800*sc));\n app.style.transform=`translate(${s==1?0:f}px,${s==1?0:g}px) scale(${sc})`}\nfunction toast(html,top,left,w,vis,kind){}\nfunction setTxt(el,v){if(el.__v!==v){el.textContent=v;el.__v=v}}\nfunction setHtml(el,v){if(el.__v!==v){el.innerHTML=v;el.__v=v}}\nfunction setSt(el,k,v){if(el.__s===undefined)el.__s={};if(el.__s[k]!==v){el.style[k]=v;el.__s[k]=v}}\nfunction el(h){const d=document.createElement('div');d.innerHTML=h.trim();return d.firstChild}\n<\/script>\n<style>\n.h1{left:210px;top:58px}.sub{left:210px;top:84px}\n.cc{position:absolute;background:#fff;border:1px solid #ecebf0;border-radius:12px;box-shadow:0 1px 2px rgba(30,20,40,.03);overflow:hidden}\n.ct{position:absolute;left:16px;top:13px;font-size:13px;font-weight:700;white-space:nowrap}\n.cs{position:absolute;right:16px;top:14px;font-size:10.5px;color:#8a8a96;white-space:nowrap}\n.tag{display:inline-flex;align-items:center;gap:4px;height:18px;padding:0 7px;border-radius:5px;font-size:10px;font-weight:700;white-space:nowrap}\n.pk{background:#ffe7f3;color:#d6287f}.gr{background:#e2f6ec;color:#0f9b66}.rd{background:#ffe3e8;color:#e5384c}.gy{background:#efeef2;color:#555}.bl{background:#e3ecff;color:#2f5fd0}.am{background:#fff0d2;color:#c77a00}\n.pbtn{position:absolute;height:34px;border-radius:9px;background:linear-gradient(90deg,#ec2f8c,#f06bb0);color:#fff;font-size:12.5px;font-weight:700;display:flex;align-items:center;justify-content:center;gap:6px;box-shadow:0 6px 1